import {Stack} from '@primer/react'
import {MetricCard} from './MetricCard'
import type {ReactNode} from 'react'

export type CardConfig = {
  title: string
  value: ReactNode
  description: string
  linkLabel?: string
  linkUrl?: string
  children?: ReactNode
}

type MetricCardsProps = {
  cards: CardConfig[]
}

const MetricCards = ({cards}: MetricCardsProps) => (
  <Stack direction="horizontal" justify="space-between" className="flex-xl-row flex-column">
    {cards.map(card => (
      <Stack.Item key={card.title} grow className="width-full">
        <MetricCard {...card} />
      </Stack.Item>
    ))}
  </Stack>
)

export default MetricCards

try{ MetricCards.displayName ||= 'MetricCards' } catch {}