import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import PeriodFilter from './PeriodFilter'
import {ExportDialog} from '../ExportDialog'
import {Banner} from '@primer/react'
import {useState} from 'react'
import {UsageInfoButton} from '../info-button/UsageInfoButton'
import {CodeGenerationInfoButton} from '../info-button/CodeGenerationInfoButton'

interface HeaderProps {
  title: string
  slug: string
  businessId: number
  exportFilesUrl: string
  disableControls?: boolean
  page: 'usage' | 'code-generation'
}

const SURVEY_LINK = 'https://survey3.medallia.com/?CLDUL5-copilot-metrics'

export function Header({title, slug, businessId, exportFilesUrl, disableControls = false, page}: HeaderProps) {
  const [exportError, setExportError] = useState<string | null>(null)

  return (
    <>
      {exportError && (
        <Banner
          variant="critical"
          data-testid="export-error"
          onDismiss={() => setExportError(null)}
          title="Export Error"
          hideTitle
        >
          <Banner.Description>{exportError}</Banner.Description>
        </Banner>
      )}
      <div data-testid={'header'} className="d-flex flex-lg-row flex-justify-end gap-3 flex-column">
        <div className="flex-order-1 mr-auto flex-lg-order-none">
          <h1 data-hpc>
            {title}
            <span>
              {page === 'usage' && <UsageInfoButton />}
              {page === 'code-generation' && <CodeGenerationInfoButton />}
            </span>
          </h1>
        </div>
        <div
          data-testid={'control-bar-wide'}
          className="d-none d-lg-flex d-xl-none flex-column gap-3 flex-order-0 ml-auto"
        >
          <div>
            <BetaLabel feedbackUrl={SURVEY_LINK} aria-label="Beta label wide" />
          </div>
          {!disableControls && (
            <div className="d-flex flex-row gap-2">
              <PeriodFilter />
              <ExportDialog
                slug={slug}
                businessId={businessId}
                exportFilesUrl={exportFilesUrl}
                disableExport={disableControls}
                onError={setExportError}
              />
            </div>
          )}
        </div>
        <div
          data-testid={'control-bar-narrow'}
          className="flex-order-0 ml-auto d-lg-none d-xl-block flex-lg-order-0 mt-1"
        >
          <BetaLabel feedbackUrl={SURVEY_LINK} aria-label="Beta label narrow" />
        </div>
        {!disableControls && (
          <div className="flex-order-2 d-lg-none d-xl-block flex-lg-order-2">
            <div className="d-flex flex-lg-row flex-column gap-2">
              <PeriodFilter />
              <ExportDialog
                slug={slug}
                businessId={businessId}
                exportFilesUrl={exportFilesUrl}
                disableExport={disableControls}
                onError={setExportError}
              />
            </div>
          </div>
        )}
      </div>
    </>
  )
}

try{ Header.displayName ||= 'Header' } catch {}