import {Blankslate} from '@primer/react/experimental'
import {AlertIcon, GraphIcon} from '@primer/octicons-react'
import styles from '../styles/CopilotInsightsStyles.module.css'

interface CopilotBlankslateProps {
  type: 'welcome' | 'error' | 'policy-disabled'
  dashboardType: 'usage' | 'code-generation'
  copilotLicenseManagementLink?: string
  aiControlsLink?: string
  testId: string
}

export function CopilotBlankslate({
  type,
  dashboardType,
  copilotLicenseManagementLink,
  aiControlsLink,
  testId,
}: CopilotBlankslateProps) {
  const isWelcome = type === 'welcome'
  const isPolicyDisabled = type === 'policy-disabled'
  const isUsageDashboard = dashboardType === 'usage'

  const getHeading = () => {
    if (isPolicyDisabled) {
      return 'Copilot usage metrics are currently disabled'
    }
    if (isWelcome) {
      return isUsageDashboard
        ? 'Welcome to the Copilot IDE usage dashboard'
        : 'Welcome to the Copilot code generation dashboard'
    }
    return isUsageDashboard ? 'Copilot usage dashboard cannot be loaded' : 'Code generation dashboard cannot be loaded'
  }

  const getWelcomeDescription = () => {
    const insightsType = isUsageDashboard ? 'insights' : 'code generation insights'
    return (
      <>
        If you&apos;ve recently enabled Copilot, it may take up to a week for {insightsType} to become available.
        <br />
        Check back later for updates, or consider granting Copilot access to more organizations while you wait.
      </>
    )
  }

  const getPolicyDisabledDescription = () => {
    if (isUsageDashboard) {
      return (
        <>
          Enable Copilot usage metrics to track adoption and identify opportunities to increase Copilot usage across
          <br />
          your enterprise, or ask an enterprise manager to enable them.
        </>
      )
    }
    return (
      <>
        Enable Copilot usage metrics to track how code is generated by users and agents across your enterprise,
        <br />
        or ask an enterprise manager to enable them.
      </>
    )
  }

  const getErrorDescription = () => (
    <>
      This dashboard is temporarily unavailable due to a system error.
      <br />
      If the problem persists, contact support for assistance.
    </>
  )

  const getDescription = () => {
    if (isPolicyDisabled) return getPolicyDisabledDescription()
    if (isWelcome) return getWelcomeDescription()
    return getErrorDescription()
  }

  const getSecondaryActions = () => {
    if (isWelcome) {
      return (
        <Blankslate.SecondaryAction href={copilotLicenseManagementLink || ''}>
          Manage Copilot licenses
        </Blankslate.SecondaryAction>
      )
    }
    if (isPolicyDisabled) {
      return (
        <Blankslate.SecondaryAction href={aiControlsLink || ''}>
          Manage Copilot usage metrics
        </Blankslate.SecondaryAction>
      )
    }
    return null
  }

  return (
    <div data-testid={testId}>
      <Blankslate border>
        <Blankslate.Visual>
          {isWelcome || isPolicyDisabled ? (
            <GraphIcon size="medium" aria-label="Graph icon" />
          ) : (
            <AlertIcon size="medium" aria-label="Alert icon" />
          )}
        </Blankslate.Visual>
        <Blankslate.Heading>{getHeading()}</Blankslate.Heading>
        <Blankslate.Description className={styles.CopilotUsageBlankslateDescription}>
          {getDescription()}
        </Blankslate.Description>
        {getSecondaryActions()}
      </Blankslate>
    </div>
  )
}

try{ CopilotBlankslate.displayName ||= 'CopilotBlankslate' } catch {}